import {stages,payScenario,summarizeEarnings} from './earnings.js';
import {lifestyleSnapshot} from './lifestyle-state.js';
import {money} from './lifestyle-ui.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const span=r=>r?(r.low===r.high?money(r.low):money(r.low)+'–'+money(r.high)):'Not available';
const goalReady=g=>g.status==='ready'&&g.confirmed;
function coverage(x,g){if(!goalReady(g))return'Review your lifestyle to compare this evidence with your budget.';if(!x.range)return'No local annual wage evidence for these examples.';return`${x.covers} of ${x.range.count} ${x.covers===1?'covers':'cover'} your budget; ${x.breathingRoom} also ${x.breathingRoom===1?'leaves':'leave'} 20% breathing room.`;}
function monthlySpan(x,g){if(!goalReady(g))return'';const values=x.scenarios.map(r=>r.remaining).filter(Number.isFinite);if(!values.length)return'';const label=v=>money(Math.abs(v))+(v<0?' short':' left'),low=Math.min(...values),high=Math.max(...values);return `<p class="monthly-span"><strong>Monthly budget result:</strong> ${label(low)}${Math.abs(high-low)>.5?' to '+label(high):''}.</p>`;}
const stat=(label,x,g,compact)=>`<div class="earning-stat"><span>${label}</span><strong>${span(x.range)}<small> / year before tax</small></strong><p>${coverage(x,g)}</p>${compact?'':monthlySpan(x,g)}</div>`;
export function earningSummary(p,meta,draft,{compact=false}={}){
 const rows=meta?.pathways[p.id]||[],s=summarizeEarnings(rows,draft),later=rows.length-s.total;
 return`<section class="earning-summary ${compact?'compact':''}" aria-label="Earning possibilities for ${h(p.title)}"><span class="eyebrow">Earnings & my lifestyle · Austin · 2025</span><p class="earning-basis">${s.total} selected qualifying-route ${s.total===1?'example':'examples'}</p>${stat('Lower-paid-worker averages',s.entry,s.goal,compact)}${stat('All-worker medians',s.median,s.goal,compact)}<p class="subtle">${s.entry.missing||s.median.missing?'Some selected examples lack local annual pay data. ':''}${later} further-study or experienced ${later===1?'destination is':'destinations are'} shown separately. These spans describe selected examples, not earnings for a degree.</p><a class="text-link" href="#/path/${p.id}?view=earnings">See earning evidence & requirements ↗</a></section>`;
}
export function earningsIntro(meta){return`<aside class="earnings-intro"><strong>Compare possibilities, without choosing a profession.</strong><p>Each pathway shows selected earning examples after their own qualifying routes. Lower-paid-worker averages and all-worker medians are different views of today’s workforce, not a promised salary progression. Shortlist up to three pathways to compare them side by side.</p><a href="#/about?section=earnings" class="text-link">How the earning comparison works ↗</a></aside>`;}
function monthly(r,key,goal){const x=payScenario(r[key],goal);if(x.status==='missing')return'<span class="subtle">No local annual figure</span>';if(x.status==='no-goal')return'';const amount=money(Math.abs(x.remaining));return`<span class="monthly-result ${x.status==='shortfall'?'gap':'covered'}">${x.status==='shortfall'?amount+' / month short':amount+' / month left'}${x.status==='breathing-room'?' · includes breathing room':''}</span>`;}
function sourceRow(r,goal){return`<tr><th scope="row"><strong>${h(r.title)}</strong><small>${h(r.education)}${r.experience!=='None'?' · '+h(r.experience)+' related experience':''}${r.training!=='None'?' · '+h(r.training):''}</small>${r.routeNote?`<small>${h(r.routeNote)} ${h(r.routeCaution)}</small>`:''}<a href="${h(r.preparationURL)}" target="_blank" rel="noopener">Preparation source ↗</a></th><td data-label="Lower-paid-worker average">${r.entry?money(r.entry):'Not available'}${monthly(r,'entry',goal)}</td><td data-label="All-worker median">${r.median?money(r.median):'Not available'}${monthly(r,'median',goal)}<a href="${h(r.wageURL)}" target="_blank" rel="noopener">Local wage source ↗</a></td></tr>`;}
export function earningsMethod(meta){return`<details class="panel earnings-method" id="earnings-method"><summary>Sources & how to read these numbers</summary><p><strong>${h(meta.geography)} · ${h(meta.wagePeriod)} annual wages.</strong> The Texas Workforce Commission snapshot was collected ${h(meta.snapshotDate)}. These are dated local observations, not inflation-adjusted forecasts for when you graduate. No statewide or national pay is substituted when local data is missing.</p><p><strong>Lower-paid-worker average:</strong> the mean for the lowest-paid third of workers in each occupation. TWC calls this its entry wage. It is a useful comparison point, not an observed starting salary for new college graduates.</p><p><strong>All-worker median:</strong> half of workers in that occupation earn less and half earn more. It mixes experience levels; it does not show what you will earn after a set number of years.</p><p>Spans are the minimum and maximum of a small editorial selection of program-linked examples. They are not representative of all graduates, a statistical interval or a chance of meeting your goal. Each six-digit wage group counts once within a pathway; narrow O*NET specialties do not multiply the evidence. Different pathways can share an example.</p><p>Preparation comes from BLS Table 1.2, 2025 worker characteristics, retrieved ${h(meta.preparationRetrieved)}. National typical education, related experience and training, plus existing reviewed credential notes, help separate the branches. Where a reviewed graduate requirement is stricter, the example stays in further study (including new RDN exam eligibility); they do not verify a named program’s accreditation or licensing eligibility. Check the exact credential, supervised practice, examinations and local rules. A broad pathway does not qualify you for every example.</p><p>Monthly comparisons apply your confirmed spending, cash-saving, debt, health and retirement settings to the same 2026 single-filer employee tax model. Health is subtracted once and retirement is capped at $24,500. The illustration assumes 40 hours and 52 paid weeks in Texas. Annual occupational wages do not guarantee full-year work; creative and freelance income may be especially variable, and self-employment is not modeled here.</p><p>“Covers” means estimated take-home after health covers your entered spending and cash saving. “Breathing room” also leaves 20% of that take-home. Tuition, additional training costs and future loan payments are excluded unless you enter them into your budget. Owning a home and buying a car can also require upfront cash.</p><ul><li><a href="${h(meta.wageDefinitionsURL)}" target="_blank" rel="noopener">TWC wage definitions</a></li><li><a href="${h(meta.preparationURL)}" target="_blank" rel="noopener">BLS preparation table</a></li><li><a href="./data/pathway-earnings.json" target="_blank" rel="noopener">Inspect selected examples & source fingerprints (JSON)</a></li></ul><p><a href="https://www.cdrnet.org/graduatedegree" target="_blank" rel="noopener">CDR graduate-degree requirement for new RDN exam eligibility</a> explains the dietetics distinction from the broad BLS education category.</p><p>Lifestyle comparisons do not change your interest scores or remove pathways.</p></details>`;}
export function earningsPage(p,meta,draft){const rows=meta.pathways[p.id]||[],goal=lifestyleSnapshot(draft);return`<div class="earnings-heading"><span class="eyebrow">Different futures can share a beginning</span><h2>What could this pathway support?</h2><p class="lede">Compare earning possibilities with the life you’re picturing. You do not need to choose any of these professions.</p></div>${earningSummary(p,meta,draft)}${!goalReady(goal)?'<div class="note">Your earning evidence is available. <a href="#/lifestyle">Create or review a lifestyle budget</a> to see monthly gaps and breathing room.</div>':`<div class="note">Your confirmed budget needs about <strong>${money(goal.range.low)} / year</strong> before tax, or <strong>${money(goal.range.high)}</strong> with breathing room. Monthly amounts below include your spending and cash-saving goals.${goal.inputs.housingMode==='own'?' Home ownership also has an upfront cash gap of '+money(goal.result.upfrontGap)+'.':''}${goal.result.carUpfront>0?' Car down payment: '+money(goal.result.carUpfront)+' upfront.':''}</div>`}${stages.map(stage=>{const examples=rows.filter(r=>r.stage===stage.id);return`<section class="panel earnings-stage"><h3>${stage.title}</h3><p>${stage.copy}</p>${examples.length?`<p class="subtle">${examples.length} selected ${examples.length===1?'example':'examples'} · annual wages before tax · Austin metro, 2025</p><div class="earnings-table-wrap"><table class="earnings-table"><caption class="sr-only">${h(stage.title)}: wage evidence and budget comparison</caption><thead><tr><th scope="col">Illustrative destination & preparation</th><th scope="col">Lower-paid-worker average</th><th scope="col">All-worker median</th></tr></thead><tbody>${examples.map(r=>sourceRow(r,goal)).join('')}</tbody></table></div>`:'<p class="subtle">No examples selected in this group. This does not establish that the pathway has no such destinations.</p>'}</section>`;}).join('')}<section class="panel"><h3>A useful college question</h3><p>Which specific programs prepare students for the qualifying routes I might want to keep open? Compare their net cost, completion time, work placements and published graduate outcomes alongside this occupational evidence.</p><a href="#/plan" class="text-link">Plan my college questions ↗</a></section>${earningsMethod(meta)}`;}
